# Excel to CSV Converter using Qt5

Here's a complete Qt5 application that converts Excel files to CSV format:

## Project Structure

### excel_converter.pro
```qmake
QT += core gui widgets

greaterThan(QT_MAJOR_VERSION, 4): QT += widgets

TARGET = ExcelConverter
TEMPLATE = app

CONFIG += c++11

SOURCES += \
    main.cpp \
    mainwindow.cpp

HEADERS += \
    mainwindow.h

# For Excel file handling, we'll use QAxObject (Windows only) or external library
win32 {
    QT += axcontainer
    DEFINES += USE_AXOBJECT
}
```

### mainwindow.h
```cpp
#ifndef MAINWINDOW_H
#define MAINWINDOW_H

#include <QMainWindow>
#include <QPushButton>
#include <QTextEdit>
#include <QVBoxLayout>
#include <QProgressBar>
#include <QLabel>

class MainWindow : public QMainWindow
{
    Q_OBJECT

public:
    MainWindow(QWidget *parent = nullptr);
    ~MainWindow();

private slots:
    void selectDirectory();
    void convertFiles();

private:
    QPushButton *selectDirButton;
    QPushButton *convertButton;
    QTextEdit *logTextEdit;
    QLabel *directoryLabel;
    QProgressBar *progressBar;

    QString selectedDirectory;

    void setupUI();
    void logMessage(const QString &message);
    bool convertExcelToCSV(const QString &excelFilePath, const QString &csvFilePath);
    QStringList findExcelFiles(const QString &directory);

#ifdef USE_AXOBJECT
    bool convertExcelToCSV_Windows(const QString &excelFilePath, const QString &csvFilePath);
#endif
};

#endif // MAINWINDOW_H
```

### mainwindow.cpp
```cpp
#include "mainwindow.h"
#include <QFileDialog>
#include <QDir>
#include <QFile>
#include <QTextStream>
#include <QMessageBox>
#include <QDateTime>

#ifdef USE_AXOBJECT
#include <QAxObject>
#endif

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
{
    setupUI();
}

MainWindow::~MainWindow()
{
}

void MainWindow::setupUI()
{
    setWindowTitle("Excel to CSV Converter");
    setMinimumSize(600, 400);

    // Create central widget and layout
    QWidget *centralWidget = new QWidget(this);
    QVBoxLayout *mainLayout = new QVBoxLayout(centralWidget);

    // Directory selection section
    QLabel *titleLabel = new QLabel("Select a directory containing Excel files", this);
    titleLabel->setStyleSheet("font-size: 14px; font-weight: bold;");
    mainLayout->addWidget(titleLabel);

    selectDirButton = new QPushButton("Select Directory", this);
    selectDirButton->setMinimumHeight(40);
    mainLayout->addWidget(selectDirButton);

    directoryLabel = new QLabel("No directory selected", this);
    directoryLabel->setStyleSheet("color: gray; padding: 5px;");
    mainLayout->addWidget(directoryLabel);

    // Convert button
    convertButton = new QPushButton("Convert Excel Files to CSV", this);
    convertButton->setMinimumHeight(40);
    convertButton->setEnabled(false);
    convertButton->setStyleSheet("background-color: #4CAF50; color: white; font-weight: bold;");
    mainLayout->addWidget(convertButton);

    // Progress bar
    progressBar = new QProgressBar(this);
    progressBar->setVisible(false);
    mainLayout->addWidget(progressBar);

    // Log area
    QLabel *logLabel = new QLabel("Log:", this);
    mainLayout->addWidget(logLabel);

    logTextEdit = new QTextEdit(this);
    logTextEdit->setReadOnly(true);
    mainLayout->addWidget(logTextEdit);

    setCentralWidget(centralWidget);

    // Connect signals
    connect(selectDirButton, &QPushButton::clicked, this, &MainWindow::selectDirectory);
    connect(convertButton, &QPushButton::clicked, this, &MainWindow::convertFiles);
}

void MainWindow::selectDirectory()
{
    QString directory = QFileDialog::getExistingDirectory(
        this,
        "Select Directory with Excel Files",
        QDir::homePath(),
        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
    );

    if (!directory.isEmpty())
    {
        selectedDirectory = directory;
        directoryLabel->setText("Selected: " + selectedDirectory);
        directoryLabel->setStyleSheet("color: green; padding: 5px;");
        convertButton->setEnabled(true);
        logMessage("Directory selected: " + selectedDirectory);
    }
}

void MainWindow::convertFiles()
{
    if (selectedDirectory.isEmpty())
    {
        QMessageBox::warning(this, "No Directory", "Please select a directory first.");
        return;
    }

    // Find all Excel files
    QStringList excelFiles = findExcelFiles(selectedDirectory);

    if (excelFiles.isEmpty())
    {
        QMessageBox::information(this, "No Files", "No Excel files found in the selected directory.");
        logMessage("No Excel files found.");
        return;
    }

    logMessage(QString("Found %1 Excel file(s)").arg(excelFiles.size()));

    // Create output directory
    QString outputDir = selectedDirectory + "/CSV_Output";
    QDir dir;
    if (!dir.exists(outputDir))
    {
        if (dir.mkpath(outputDir))
        {
            logMessage("Created output directory: " + outputDir);
        }
        else
        {
            QMessageBox::critical(this, "Error", "Failed to create output directory.");
            return;
        }
    }

    // Show progress bar
    progressBar->setVisible(true);
    progressBar->setMaximum(excelFiles.size());
    progressBar->setValue(0);

    // Disable buttons during conversion
    selectDirButton->setEnabled(false);
    convertButton->setEnabled(false);

    // Convert each file
    int successCount = 0;
    for (int i = 0; i < excelFiles.size(); ++i)
    {
        QString excelFilePath = excelFiles[i];
        QFileInfo fileInfo(excelFilePath);
        QString csvFileName = fileInfo.completeBaseName() + ".csv";
        QString csvFilePath = outputDir + "/" + csvFileName;

        logMessage(QString("Converting: %1...").arg(fileInfo.fileName()));

        if (convertExcelToCSV(excelFilePath, csvFilePath))
        {
            logMessage(QString("  ✓ Success: %1").arg(csvFileName));
            successCount++;
        }
        else
        {
            logMessage(QString("  ✗ Failed: %1").arg(fileInfo.fileName()));
        }

        progressBar->setValue(i + 1);
        QApplication::processEvents(); // Keep UI responsive
    }

    // Re-enable buttons
    selectDirButton->setEnabled(true);
    convertButton->setEnabled(true);

    // Show completion message
    QString message = QString("Conversion complete!\n%1 of %2 files converted successfully.")
                          .arg(successCount)
                          .arg(excelFiles.size());
    logMessage(message);
    QMessageBox::information(this, "Complete", message);
}

QStringList MainWindow::findExcelFiles(const QString &directory)
{
    QDir dir(directory);
    QStringList filters;
    filters << "*.xlsx" << "*.xls" << "*.xlsm";

    QStringList excelFiles;
    QFileInfoList fileList = dir.entryInfoList(filters, QDir::Files);

    for (const QFileInfo &fileInfo : fileList)
    {
        excelFiles.append(fileInfo.absoluteFilePath());
    }

    return excelFiles;
}

bool MainWindow::convertExcelToCSV(const QString &excelFilePath, const QString &csvFilePath)
{
#ifdef USE_AXOBJECT
    return convertExcelToCSV_Windows(excelFilePath, csvFilePath);
#else
    // For non-Windows platforms, you would need to use external libraries
    // like libxlsxwriter, xlnt, or call Python scripts
    logMessage("Error: Excel conversion not supported on this platform.");
    logMessage("Please compile on Windows with QAxObject support.");
    return false;
#endif
}

#ifdef USE_AXOBJECT
bool MainWindow::convertExcelToCSV_Windows(const QString &excelFilePath, const QString &csvFilePath)
{
    QAxObject *excel = new QAxObject("Excel.Application");

    if (!excel || excel->isNull())
    {
        logMessage("Error: Could not start Excel application. Make sure Microsoft Excel is installed.");
        delete excel;
        return false;
    }

    excel->setProperty("Visible", false);
    excel->setProperty("DisplayAlerts", false);

    QAxObject *workbooks = excel->querySubObject("Workbooks");
    if (!workbooks)
    {
        delete excel;
        return false;
    }

    QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", 
                                                     QDir::toNativeSeparators(excelFilePath));
    if (!workbook)
    {
        delete workbooks;
        delete excel;
        return false;
    }

    // Save as CSV (file format 6 = CSV)
    bool success = false;
    QVariant result = workbook->dynamicCall("SaveAs(const QString&, int)", 
                                            QDir::toNativeSeparators(csvFilePath), 
                                            6); // 6 = xlCSV

    if (!result.isNull())
    {
        success = true;
    }

    workbook->dynamicCall("Close(bool)", false);
    excel->dynamicCall("Quit()");

    delete workbook;
    delete workbooks;
    delete excel;

    return success;
}
#endif

void MainWindow::logMessage(const QString &message)
{
    QString timestamp = QDateTime::currentDateTime().toString("hh:mm:ss");
    logTextEdit->append(QString("[%1] %2").arg(timestamp).arg(message));
}
```

### main.cpp
```cpp
#include "mainwindow.h"
#include <QApplication>

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    MainWindow window;
    window.show();

    return app.exec();
}
```

## Building and Running

### On Windows:
```bash
qmake excel_converter.pro
make  # or nmake for MSVC
./ExcelConverter
```

### Features:
- ✓ Simple, user-friendly GUI
- ✓ Directory selection dialog
- ✓ Finds all Excel files (.xlsx, .xls, .xlsm)
- ✓ Creates a "CSV_Output" folder
- ✓ Progress bar showing conversion status
- ✓ Detailed logging
- ✓ Error handling

### Notes:
1. **Windows**: Uses QAxObject to interface with Microsoft Excel (requires Excel installed)
2. **Linux/Mac**: You'll need to integrate external libraries like:
   - [xlnt](https://github.com/tfussell/xlnt)
   - [libxlsxwriter](https://libxlsxwriter.github.io/)
   - Or call Python scripts using QProcess

